        if idempotency_key:
            with self.conn:
                existing_booking = self.conn.execute("SELECT * FROM bookings WHERE idempotency_key = ?", (idempotency_key,)).fetchone()
                if existing_booking:
                    return dict(existing_booking)

        with self.conn:
            slot = self.conn.execute("SELECT slot_id, status FROM slots WHERE counselor_id = ? AND start_time = ?", (counselor_id, start_time)).fetchone()
            if not slot:
                raise ValueError("Slot not found")
            if slot["status"] != "AVAILABLE":
                raise ValueError(f"Slot is not available (status: {slot['status']})")

            pass_record = self.conn.execute("SELECT remaining_sessions FROM session_passes WHERE client_email = ?", (client_email,)).fetchone()
