            self.conn.execute("INSERT INTO bookings (booking_id, counselor_id, start_time, client_name, client_email, status, idempotency_key) VALUES (?, ?, ?, ?, ?, ?, ?)", 
                              (booking_id, counselor_id, start_time, client_name, client_email, "CONFIRMED", idempotency_key))

            self.conn.execute("INSERT INTO audit_logs (booking_id, event_type, from_status, to_status, timestamp) VALUES (?, ?, ?, ?, ?)", 
                              (booking_id, "BOOKING_CREATED", None, "CONFIRMED", datetime.now().isoformat()))

            return self.lookup_booking(booking_id, client_email)

    def lookup_booking(self, booking_id: str, client_email: str):
        with self.conn:
            booking = self.conn.execute("SELECT * FROM bookings WHERE booking_id = ?", (booking_id,)).fetchone()
            if not booking:
                raise ValueError("Booking not found")
            if booking["client_email"] != client_email:
                raise PermissionError("Booking does not belong to the provided email")
            return dict(booking)

