                if pass_record:
                    self.conn.execute("UPDATE session_passes SET remaining_sessions = remaining_sessions - 1, used_sessions = used_sessions + 1 WHERE client_email = ?", (entry["client_email"],))
                else:
                    self.conn.execute("INSERT INTO session_passes (client_email, remaining_sessions, used_sessions) VALUES (?, ?, ?)", (entry["client_email"], remaining - 1, 1))

                new_booking_id = str(uuid.uuid4())
                self.conn.execute("INSERT INTO pass_ledger (client_email, booking_id, entry_type, delta_sessions, idempotency_key) VALUES (?, ?, ?, ?, ?)", 
                                  (entry["client_email"], new_booking_id, "USE", -1, f"use_{new_booking_id}"))

                self.conn.execute("INSERT INTO bookings (booking_id, counselor_id, start_time, client_name, client_email, status, idempotency_key) VALUES (?, ?, ?, ?, ?, ?, ?)", 
                                  (new_booking_id, counselor_id, start_time, entry["client_name"], entry["client_email"], "CONFIRMED", None))

                self.conn.execute("INSERT INTO audit_logs (booking_id, event_type, from_status, to_status, timestamp) VALUES (?, ?, ?, ?, ?)", 
                                  (new_booking_id, "WAITLIST_PROMOTED", None, "CONFIRMED", datetime.now().isoformat()))

