            pass_record = self.conn.execute("SELECT remaining_sessions FROM session_passes WHERE client_email = ?", (client_email,)).fetchone()
            remaining = pass_record["remaining_sessions"] if pass_record else 0
            if remaining < 1:
                raise ValueError("Insufficient session passes to join waitlist")

            self.conn.execute("INSERT INTO waitlist (counselor_id, start_time, client_name, client_email, status) VALUES (?, ?, ?, ?, ?)", 
                              (counselor_id, start_time, client_name, client_email, "WAITING"))

    def cancel_booking(self, booking_id: str, client_email: str):
